import sys, math, time
from sympy import factorint
from collections import defaultdict

def prime_factors(n):
    return set(factorint(n).keys())

def generate_sequence(a1, N, cap=10**7):
    """Efficient generator. Track per-prime set of term indices."""
    seq = [a1]
    psets = [prime_factors(a1)]
    # prime -> set of term indices it divides
    pidx = defaultdict(set)
    for p in psets[0]:
        pidx[p].add(0)
    Pall = set(psets[0])  # union of primes seen
    n = 1
    for _ in range(N-1):
        a_n = seq[-1]
        cand = a_n + 1
        while True:
            # quick reject: must be divisible by some prime in Pall
            # factor cand
            cps = set(factorint(cand).keys())
            if not (cps & Pall):
                cand += 1
                continue
            # full check: union of pidx[p] for p in cps must cover {0..n-1}
            covered = set()
            target = n
            for p in cps:
                if p in pidx:
                    covered |= pidx[p]
                    if len(covered) == target:
                        break
            if len(covered) == target:
                seq.append(cand)
                psets.append(cps)
                for p in cps:
                    pidx[p].add(n)
                Pall |= cps
                n += 1
                break
            cand += 1
            if cand > a_n + cap:
                return seq, psets, dict(pidx), Pall
    return seq, psets, dict(pidx), Pall

if __name__ == '__main__':
    t=time.time()
    s,ps,pidx,Pall = generate_sequence(6, 60)
    print('a1=6:', s)
    print('time', time.time()-t)
    # primes dividing all terms
    common = None
    for p, idxs in pidx.items():
        if len(idxs) == len(s):
            print('common prime:', p)

