import sys, time
from sympy import factorint
from collections import defaultdict

def prime_factors(n):
    return set(factorint(n).keys())

def generate_sequence(a1, N, cap=10**7):
    seq = [a1]
    psets = [prime_factors(a1)]
    pidx = defaultdict(set)
    for p in psets[0]:
        pidx[p].add(0)
    Pall = set(psets[0])
    n = 1
    for _ in range(N-1):
        a_n = seq[-1]
        cand = a_n + 1
        while True:
            cps = set(factorint(cand).keys())
            if not (cps & Pall):
                cand += 1
                continue
            covered = set()
            target = n
            for p in cps:
                if p in pidx:
                    covered |= pidx[p]
                    if len(covered) == target:
                        break
            if len(covered) == target:
                seq.append(cand)
                psets.append(cps)
                for p in cps:
                    pidx[p].add(n)
                Pall |= cps
                n += 1
                break
            cand += 1
            if cand > a_n + cap:
                return seq, psets, dict(pidx), Pall, False
    return seq, psets, dict(pidx), Pall, True

def detect_period(seq, Tmax=20, Nmin=None):
    """Find N, T, L such that for all n>=N (0-indexed), seq[n+T]-seq[n]==L constant.
    Search smallest N after which some (T<=Tmax) gives constant L for tail."""
    N = len(seq)
    best = None
    # try N from 1 up
    for start in range(1, N - Tmax - 2):
        for T in range(1, Tmax+1):
            if start + 2*T >= N:
                continue
            L = seq[start+T] - seq[start]
            ok = True
            for k in range(start, N - T):
                if seq[k+T] - seq[k] != L:
                    ok = False
                    break
            if ok and (best is None or start < best[0] or (start==best[0] and T<best[1])):
                best = (start, T, L)
                break
        if best and best[0]==start:
            break
    return best  # (start_index_0based, T, L)

def run_batch(a1_list, N=4000):
    results = []
    t0 = time.time()
    for a1 in a1_list:
        seq, ps, pidx, Pall, ok = generate_sequence(a1, N)
        per = detect_period(seq, Tmax=20)
        # active prime set in tail
        if per:
            st, T, L = per
            tail = seq[st:]
            active = set()
            for x in tail[:T] if T<=len(tail) else tail:
                active |= set(factorint(x).keys())
            common = [p for p,s in pidx.items() if len(s)==len(seq)]
            results.append((a1, T, L, st, sorted(common), sorted(active)[:8]))
    return results, time.time()-t0

if __name__ == '__main__':
    a1_list = list(range(2, 201))
    res, dt = run_batch(a1_list, N=1500)
    print('total time', dt)
    print('a1 | T | L | transient_start | common_primes | active_tail_primes')
    for r in res:
        print(r)

