    fs = set(factorint(abs(m)).keys())
    return frozenset(q for q in fs if q in PR)  # PR is set of primes <= R

def minimal_hitting_sets(family):
    """Return set of inclusion-minimal hitting sets of family (list of sets).
    Brute force over subsets of universe."""
    universe = set()
    for s in family:
        universe |= set(s)
