    minimal = []
    for h in hits:
        if not any(other < h for other in hits if other <= h and other != h):
            minimal.append(frozenset(h))
    # dedupe
    seen = set()
    out = []
    for h in minimal:
        if h not in seen:
            seen.add(h)
            out.append(h)
